@Override
public UElementHandler createUastHandler(@NotNull JavaContext context) {
    return new UElementHandler() {
        @Override
        public void visitClass(@NotNull UClass node) {
            // skip interfaces, annotations, enums, abstract
            if (node.isInterface() || node.isAnnotationType() || node.isEnum()) return;
            if (node.hasModifierProperty(PsiModifier.ABSTRACT)) return; // skip abstract
            String fqcn = node.getQualifiedName();
            if (fqcn == null) return;
            if (context.getEvaluator().extendsClass(node, "android.app.Activity", false)) {
                mClasses.add(new ComponentInfo(fqcn, node, context, "activity"));
            } else if (context.getEvaluator().extendsClass(node, "android.app.Service", false)) {
                mClasses.add(new ComponentInfo(fqcn, node, context, "service"));
            } else if (context.getEvaluator().extendsClass(node, "android.content.ContentProvider", false)) {
                mClasses.add(new ComponentInfo(fqcn, node, context, "provider"));
            }
        }
    };
}

